const $=s=>document.querySelector(s);let leads=[],setup=false;
async function api(action='',method='GET',body){const response=await fetch('/api/leads'+(action?'?action='+action:''),{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data;try{data=await response.json()}catch{throw Error('O painel está indisponível. Tente novamente.')}if(!response.ok){if(response.status===401){$('#contacts').hidden=true;$('#auth').hidden=false;$('#logout').hidden=true}throw Error(data.error||'Não foi possível concluir.')}return data;}
function notice(text){$('#notice').textContent=text;}
function element(tag,text,className){const node=document.createElement(tag);if(text)node.textContent=text;if(className)node.className=className;return node;}
function render(){const term=$('#search').value.toLocaleLowerCase(),status=$('#filter').value;const shown=leads.filter(l=>(status==='Todos'||l.status===status)&&[l.name,l.phone,l.treatment].join(' ').toLocaleLowerCase().includes(term));$('#lead-list').replaceChildren();$('#counts').replaceChildren(...['Novo','Em contato','Agendado','Concluído'].map(s=>element('p',`${s}: ${leads.filter(l=>l.status===s).length}`)));$('#result-count').textContent=`${shown.length} contato(s) encontrado(s)`;if(!shown.length)$('#lead-list').append(element('p','Nenhum contato para mostrar.'));
shown.forEach(lead=>{const card=element('article',null,'lead-item'),heading=element('div',null,'lead-heading'),title=element('div');title.append(element('h2',lead.name),element('small',new Date(lead.createdAt).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})));const select=element('select');select.setAttribute('aria-label',`Status de ${lead.name}`);['Novo','Em contato','Agendado','Concluído'].forEach(s=>{const o=element('option',s);o.selected=s===lead.status;select.append(o)});select.addEventListener('change',async()=>{select.disabled=true;try{await api('','PATCH',{id:lead.id,status:select.value});lead.status=select.value;render();notice('Status atualizado.')}catch(e){select.value=lead.status;notice(e.message)}finally{select.disabled=false}});heading.append(title,select);const contact=element('a',lead.phone+' · Abrir WhatsApp','text-link');contact.href='https://wa.me/'+(lead.phone.length<=11?'55':'')+lead.phone;contact.target='_blank';contact.rel='noopener noreferrer';card.append(heading,element('p',lead.treatment),contact);if(lead.message)card.append(element('p',lead.message));$('#lead-list').append(card)});}
async function loadLeads(){notice('Carregando contatos…');const data=await api();leads=data.leads;$('#auth').hidden=true;$('#contacts').hidden=false;$('#logout').hidden=false;render();notice('');}
async function start(){try{const info=await api('session');setup=info.setupRequired;if(info.authenticated){await loadLeads();return;}$('#auth').hidden=false;$('#setup-label').hidden=!setup;$('#setup-label input').required=setup;$('#auth-title').textContent=setup?'Crie seu acesso':'Entrar no painel';$('#auth-help').textContent=setup?'Use a chave de configuração definida na Vercel e escolha seu usuário e uma senha de pelo menos 12 caracteres.':'Acompanhe os contatos recebidos pelo site.';$('#auth-form button').textContent=setup?'Criar acesso':'Entrar';}catch(e){notice('O painel precisa estar conectado ao banco de dados. Confira a configuração da Vercel.');}}
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api(setup?'setup':'login','POST',Object.fromEntries(new FormData(e.target)));e.target.reset();setup=false;await loadLeads()}catch(error){notice(error.message)}finally{button.disabled=false}});
$('#logout').addEventListener('click',async()=>{try{await api('logout','POST',{});location.reload()}catch(e){notice(e.message)}});$('#refresh').addEventListener('click',()=>loadLeads().catch(e=>notice(e.message)));$('#search').addEventListener('input',render);$('#filter').addEventListener('change',render);start();
